from lib import *
S = SS('u167')
R = J('u167'); U = {(u[0], u[2]): u for u in R['units']}; jb = R['jobs']; M = R['mono']; P = R['prof']; I = R['inc']
chain = [('proc-macro2', 'build script'), ('proc-macro2', 'build-script (run)'), ('proc-macro2', 'lib'), ('syn', 'lib'), ('serde_derive', 'lib'), ('serde', 'lib'), ('u167p', 'u167p "bin"')]
ch = [U[k] for k in chain]; chain_sum = sum(c[4] for c in ch)
first = min(u[3] for u in R['units'])
steps = [
    step(f"cargo build --timings 生成一份 HTML 报告({R['htmlkb']} KiB),里面的 UNIT_DATA 记录每个编译单元的开始时间与耗时。serde + serde_json + regex 共 {len(R['units'])} 个单元(含各 build script 的编译与运行),整体 {R['tot']:.2f} 秒,同一时刻最多并行 10 个,单元耗时总和 {R['sum']:.2f} 秒。最长的是 regex-automata({U[('regex-automata','lib')][4]:.2f} 秒)、regex-syntax({U[('regex-syntax','lib')][4]:.2f} 秒)、serde_core({U[('serde_core','lib')][4]:.2f} 秒)。有分段信息的单元里 frontend 合计 {R['fe']:.2f} 秒、codegen 合计 {R['cg']:.2f} 秒。注意:第一个编译单元直到 {first:.2f} 秒才开始(我没有深究这段时间 cargo 在做什么)。", t=tl(S(1)), done=lidx(S(1), 'regex-automata 0.4.18', 'regex-syntax 0.8.11', 'serde_core 1.0.229     lib'), mark=lidx(S(1), '最后一个单元结束于', 'frontend 合计'), b=bars([[u[0] + ('' if u[2] == 'lib' else ' (' + u[2] + ')'), u[4], f'{u[4]:.2f} s'] for u in sorted(R['units'], key=lambda x: -x[4])[:6]], 1.5, done=[0, 1, 2, 3, 4, 5]), kv=KV([['单元数', str(len(R['units']))], ['整体', f"{R['tot']:.2f} 秒"], ['耗时总和', f"{R['sum']:.2f} 秒"]], ['整体'])),
    step(f"关键路径:最后开始的单元是项目本身 u167p({ch[-1][3]:.2f} 秒开始),直接解锁它的是 serde;serde 在 serde_derive 结束的同一时刻({ch[4][3] + ch[4][4]:.2f} 秒)才开始;serde_derive 要等 syn;syn 要等 proc-macro2。这条链上的耗时:{' → '.join(f'{c[0]} {c[4]:.2f}' for c in ch)},合计 {chain_sum:.2f} 秒。其它单元(regex 系列等)并行完成,不在关键路径上。过程宏这条链是这个项目里最长的串行依赖。", t=tl(S(1)), mark=lidx(S(1), 'serde_derive 1.0.229', 'syn 3.0.6', 'u167p 0.1.0'), done=lidx(S(1), '直接解锁'), kv=KV([['直接解锁 u167p', 'serde'], ['链', 'proc-macro2 → syn → serde_derive → serde'], ['链上耗时合计', f'{chain_sum:.2f} 秒']], ['链'])),
    step(f"并行度:同一个项目的干净构建,-j 1 中位数 {jb['-j 1']:.1f} 秒,默认(本机 10 核){jb['默认']:.1f} 秒,约 {jb['-j 1'] / jb['默认']:.1f} 倍。单元耗时总和是 {R['sum']:.1f} 秒,加速到 {jb['默认']:.1f} 秒受限于上一步的串行链。", t=tl(S(2)), b=bars([['-j 1', jb['-j 1'], f"{jb['-j 1']:.1f} s"], ['默认(10 核)', jb['默认'], f"{jb['默认']:.1f} s"]], jb['-j 1'], done=[0, 1]), kv=KV([['-j 1', f"{jb['-j 1']:.1f} 秒"], ['默认', f"{jb['默认']:.1f} 秒"]], ['默认'])),
    step(f"rustc -Z time-passes(需要 RUSTC_BOOTSTRAP=1)按阶段列出耗时。对一个生成的文件(300 个类型实现同一个 trait,泛型函数 300 次实例化,共 {R['npasses']} 个阶段,total = {R['tp_total']} 秒):最耗时的是 finish_ongoing_codegen / LLVM_passes({R['passes'][0][0]:.3f} 秒)、run_linker({R['passes'][2][0]:.3f} 秒)、MIR_borrow_checking({R['passes'][3][0]:.3f})、type_check_crate({R['passes'][4][0]:.3f})。link、link_crate、link_binary 三行都是 0.047 秒,是同一段链接工作的嵌套包装层,所以表里去掉了它们。", t=tl(S(3)), done=lidx(S(3), 'LLVM_passes', 'run_linker', 'MIR_borrow_checking', 'type_check_crate'), kv=KV([['total', f"{R['tp_total']} 秒"], ['最耗时', 'LLVM_passes、run_linker'], ['阶段数', str(R['npasses'])]], ['最耗时'])),
    step(f"泛型实例化的代价(调试构建,3 次中位数):N = 50 / 200 / 800 个类型时,泛型版本 {M[0][1]:.2f} / {M[1][1]:.2f} / {M[2][1]:.2f} 秒(print-mono-items 里 work 的实例化 {M[0][2]} / {M[1][2]} / {M[2][2]} 项);dyn 版本只有 1 份 work,耗时 {M[0][3]:.2f} / {M[1][3]:.2f} / {M[2][3]:.2f} 秒。差别不大(N = 800 时 {M[2][1] - M[2][3]:.2f} 秒):因为两个版本都要生成 N 个类型与 N 个 impl,总耗时主要随 N 增长。这个实验里的函数体很小,没有验证函数体更大时实例化份数的影响。", t=tl(S(4)), b=bars([[f'N={m[0]} 泛型', m[1], f'{m[1]:.2f} s'] for m in M] + [[f'N={m[0]} dyn', m[3], f'{m[3]:.2f} s'] for m in M], M[2][1], done=[0, 1, 2, 3, 4, 5]), kv=KV([['N=800 泛型', f'{M[2][1]:.2f} 秒,{M[2][2]} 份'], ['N=800 dyn', f'{M[2][3]:.2f} 秒,{M[2][4]} 份']], ['N=800 泛型'])),
    step(f"构建配置对干净构建的影响(serde + serde_json + regex,3 次中位数):dev 默认 {P['dev(默认,debuginfo=2)'][0]:.1f} 秒、可执行文件 {P['dev(默认,debuginfo=2)'][1]:.0f} KiB;debug=0 耗时同样 {P['dev + debug=0'][0]:.1f} 秒,文件缩到 {P['dev + debug=0'][1]:.0f} KiB(只省体积,没省时间);opt-level=1 {P['dev + opt-level=1'][0]:.1f} 秒、{P['dev + opt-level=1'][1]:.0f} KiB;release {P['release'][0]:.1f} 秒、{P['release'][1]:.0f} KiB。优化越多构建越慢,这里 release 比 dev 慢约 {P['release'][0] / P['dev(默认,debuginfo=2)'][0]:.1f} 倍。", t=tl(S(5)), b=bars([[k, v[0], f'{v[0]:.1f} s'] for k, v in P.items()], P['dev + opt-level=1'][0], done=[0, 1, 2, 3]), kv=KV([[k, f'{v[0]:.1f} s / {v[1]:.0f} KiB'] for k, v in P.items()], ['release'])),
    step(f"增量重编:干净构建 {I['clean']:.1f} 秒;没有任何改动再构建 {I['noop']:.2f} 秒;改 main.rs 里一个字符串 {I['edit']:.2f} 秒,只重编 {I['edit_n']} 个包(项目本身);给 serde_json 打开 preserve_order 特征 {I['feat']:.2f} 秒,重编 {len(I['feat_n'])} 个包:{'、'.join(I['feat_n'])}(特征变化会引入新的依赖并让依赖它的包重编)。", t=tl(S(6)), b=bars([['干净构建', I['clean'], f"{I['clean']:.2f} s"], ['无改动', I['noop'], f"{I['noop']:.2f} s"], ['改 main.rs', I['edit'], f"{I['edit']:.2f} s"], ['加特征', I['feat'], f"{I['feat']:.2f} s"]], I['clean'], done=[0, 1, 2, 3]), kv=KV([['改 main.rs', f"{I['edit']:.2f} 秒,{I['edit_n']} 个包"], ['加 preserve_order', f"{I['feat']:.2f} 秒,{len(I['feat_n'])} 个包"]], ['改 main.rs'])),
]
A = mkart('u167', 167, 'Rust,编译时间,cargo-timings,time-passes,真实验证,动画演示',
    f'用 cargo build --timings 与 rustc -Z time-passes 分析编译时间:serde + serde_json + regex 共 {len(R["units"])} 个单元整体 {R["tot"]:.2f} 秒,关键路径是 proc-macro2 → syn → serde_derive → serde;-j 1 对默认并行 {jb["-j 1"]:.1f} 对 {jb["默认"]:.1f} 秒;debug=0 不省时间;增量重编 {I["edit"]:.2f} 秒。',
    '编译慢,先要知道慢在哪里。这篇把 cargo 的 --timings 报告拆开,找出关键路径;再用 rustc 的 -Z time-passes 看各阶段;最后量几个常见旋钮(并行度、泛型、debuginfo、优化级别、增量)到底有多大效果。',
    [(f'{R["tot"]:.2f} 秒', 'serde + serde_json + regex 的一次干净构建(--timings)'), (f'{jb["-j 1"] / jb["默认"]:.1f}×', '-j 1 相对默认并行的耗时倍数'), (f'{I["edit"]:.2f} 秒', '改 main.rs 一个字符串后的增量重编')],
    [('cargo build --timings 与关键路径', '<p>增量编译的原理见<a href="rust-incremental-compilation.html">增量编译</a>,构建配置见<a href="rust-cargo-profile.html">Cargo profile</a>。</p>'), ('并行度', None), ('rustc -Z time-passes', '<p>各编译阶段的含义见<a href="rust-compile-stages.html">Rust 编译的几个阶段</a>。</p>'), ('泛型实例化', '<p>泛型单态化的细节见<a href="rust-monomorphization-codegen.html">单态化与代码生成</a>。</p>'), ('构建配置', None), ('增量重编', None)],
    steps, [ENV_U + '。cargo 1.98.1 稳定版;time-passes 与 print-mono-items 用 RUSTC_BOOTSTRAP=1;本机 10 核', '没有验证:更大的真实项目(几百个依赖)上的结果、cargo build --timings=json 的机器可读输出、-Z threads 并行前端、使用 lld/mold 等其它链接器的效果、sccache 等缓存工具、-Z self-profile 的细粒度分析', '同一个项目的干净构建:第一节带 --timings 的那次是 5.05 秒,第二节不带 --timings 的默认并行 3 次中位数是 3.2 秒。没有验证这个差别是 --timings 本身的开销、第一次运行的缓存状态还是别的原因,所以文中把第一节的各单元时间当作「这一次运行里的相对关系」'], 'compile time')
